 public MainWindow(){Theme.Load();InitializeComponent();ThemeToggle.Content=Theme.IsLight?"☾  다크 모드":"☼  화이트 모드";SourceInitialized+=(_,_)=>Theme.TitleBar(this);InitializeFlow();Closing+=(_,e)=>{if(working){cts?.Cancel();e.Cancel=true;Status.Text="작업 취소 중입니다. 완료 후 창을 닫아 주세요.";}else api?.Dispose();};}
